    const thisWeek=appointments.filter(x=>Date.parse(x.startsAt)>=start&&Date.parse(x.startsAt)<=end),today=appointments.filter(x=>new Date(x.startsAt).toDateString()===todayDate.toDateString()),attention=thisWeek.filter(x=>/scheduled|needs confirmation/i.test(x.status));
