  function callLogModal(){const d=db(),now=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);document.body.insertAdjacentHTML('beforeend',`<div class="crm-overlay" id="crmCallModal"><aside class="crm-drawer" style="transform:none"><div class="crm-drawer-head"><div><h2>Add call log</h2><p>Record the call against the same contact used by deals, tasks, and appointments.</p></div><button class="btn" data-product-close>Close</button></div><form data-call-log-form class="crm-product-form"><label>Contact<select name="leadId" required>${(d.leads||[]).map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.phone)}</option>`).join('')}</select></label><label>Direction<select name="direction"><option>Outbound</option><option>Inbound</option></select></label><label>Started<input name="startedAt" type="datetime-local" value="${now}" required></label><label>Duration (seconds)<input name="duration" type="number" min="0" value="180"></label><label>Outcome<select name="outcome"><option>Connected</option><option>Qualified</option><option>Appointment set</option><option>Promising callback</option><option>No answer</option><option>Voicemail</option></select></label><label>Owner<input name="owner" value="Michael"></label><label style="grid-column:1/-1">Notes<textarea name="notes" rows="4" required></textarea></label><button class="btn pri" type="submit">Save call log</button></form></aside></div>`)}
