  function notificationItems(){const d=db(),now=Date.now(),items=[];(d.callbacks||[]).filter(x=>x.status==='open'&&Date.parse(x.dueAt)<=now).slice(0,3).forEach(x=>{const lead=(d.leads||[]).find(l=>l.id===x.leadId);items.push({id:`callback-${x.id}`,type:'Callback due',title:lead?.name||'Contact follow-up',detail:x.reason||'Callback is ready to work',route:'conversations-callbacks',at:x.dueAt})});(d.appointments||[]).filter(x=>Date.parse(x.startsAt)>now).slice(0,2).forEach(x=>{const lead=(d.leads||[]).find(l=>l.id===x.leadId);items.push({id:`appointment-${x.id}`,type:'Upcoming appointment',title:lead?.name||x.type,detail:`${x.type} · ${fmt(x.startsAt)}`,route:'conversations-appointments',at:x.startsAt})});(d.opportunities||[]).filter(x=>!String(x.stage).startsWith('Closed')&&now-Date.parse(x.stageEnteredAt||x.updatedAt)>14*864e5).slice(0,2).forEach(x=>items.push({id:`deal-${x.id}`,type:'Stalled deal',title:x.name,detail:`${x.stage} · ${money(x.value)} · ${x.nextAction||'Next action needed'}`,route:'sales-opportunities',at:x.stageEnteredAt||x.updatedAt}));return items.sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))}
